<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;The index of the first w from the end is &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> anyString.</span><span style="color:#6F42C1;">lastIndexOf</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;w&quot;</span><span style="color:#24292E;">));</span></span>
